import{_ as e,o as d,c as a,l as s,t as o,N as i}from"./chunks/framework.Bbd9fWQx.js";const b=JSON.parse('{"title":"stat | x-cmd man (man1) | display file or file system status","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | stat - display file or file system status","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"stat | x-cmd man (man1) | display file or file system status"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | stat - display file or file system status"}]]},"headers":[],"params":{"isMan":true,"man":"stat","category":"man1","desc":"display file or file system status"},"relativePath":"man1/stat.md","filePath":"man1/stat.md"}'),r={name:"man1/stat.md"},n={class:"visually-hidden"},l=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>stat - display file or file system status</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>stat</strong> [<em>OPTION</em>]... <em>FILE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Display file or file system status.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-L</strong>, <strong>--dereference</strong></dt><dd>follow links</dd><dt><strong>-f</strong>, <strong>--file-system</strong></dt><dd>display file system status instead of file status</dd><dt><strong>--cached</strong>=<em>MODE</em></dt><dd>specify how to use cached attributes; useful on remote file systems. See MODE below</dd><dt><strong>-c</strong> <strong>--format</strong>=<em>FORMAT</em></dt><dd>use the specified FORMAT instead of the default; output a newline after each use of FORMAT</dd><dt><strong>--printf</strong>=<em>FORMAT</em></dt><dd>like <strong>--format</strong>, but interpret backslash escapes, and do not output a mandatory trailing newline; if you want a newline, include \\n in FORMAT</dd><dt><strong>-t</strong>, <strong>--terse</strong></dt><dd>print the information in terse form</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>The MODE argument of <strong>--cached</strong> can be: always, never, or default. &#39;always&#39; will use cached attributes if available, while &#39;never&#39; will try to synchronize with the latest attributes, and &#39;default&#39; will leave it up to the underlying file system.</p><p>The valid format sequences for files (without <strong>--file-system</strong>):</p><dl><dt>%a</dt><dd>permission bits in octal (note &#39;#&#39; and &#39;0&#39; printf flags)</dd><dt>%A</dt><dd>permission bits and file type in human readable form</dd><dt>%b</dt><dd>number of blocks allocated (see %B)</dd><dt>%B</dt><dd>the size in bytes of each block reported by %b</dd><dt>%C</dt><dd>SELinux security context string</dd><dt>%d</dt><dd>device number in decimal (st_dev)</dd><dt>%D</dt><dd>device number in hex (st_dev)</dd><dt>%Hd</dt><dd>major device number in decimal</dd><dt>%Ld</dt><dd>minor device number in decimal</dd><dt>%f</dt><dd>raw mode in hex</dd><dt>%F</dt><dd>file type</dd><dt>%g</dt><dd>group ID of owner</dd><dt>%G</dt><dd>group name of owner</dd><dt>%h</dt><dd>number of hard links</dd><dt>%i</dt><dd>inode number</dd><dt>%m</dt><dd>mount point</dd><dt>%n</dt><dd>file name</dd><dt>%N</dt><dd>quoted file name with dereference if symbolic link</dd><dt>%o</dt><dd>optimal I/O transfer size hint</dd><dt>%s</dt><dd>total size, in bytes</dd><dt>%r</dt><dd>device type in decimal (st_rdev)</dd><dt>%R</dt><dd>device type in hex (st_rdev)</dd><dt>%Hr</dt><dd>major device type in decimal, for character/block device special files</dd><dt>%Lr</dt><dd>minor device type in decimal, for character/block device special files</dd><dt>%t</dt><dd>major device type in hex, for character/block device special files</dd><dt>%T</dt><dd>minor device type in hex, for character/block device special files</dd><dt>%u</dt><dd>user ID of owner</dd><dt>%U</dt><dd>user name of owner</dd><dt>%w</dt><dd>time of file birth, human-readable; - if unknown</dd><dt>%W</dt><dd>time of file birth, seconds since Epoch; 0 if unknown</dd><dt>%x</dt><dd>time of last access, human-readable</dd><dt>%X</dt><dd>time of last access, seconds since Epoch</dd><dt>%y</dt><dd>time of last data modification, human-readable</dd><dt>%Y</dt><dd>time of last data modification, seconds since Epoch</dd><dt>%z</dt><dd>time of last status change, human-readable</dd><dt>%Z</dt><dd>time of last status change, seconds since Epoch</dd></dl><p>Valid format sequences for file systems:</p><dl><dt>%a</dt><dd>free blocks available to non-superuser</dd><dt>%b</dt><dd>total data blocks in file system</dd><dt>%c</dt><dd>total file nodes in file system</dd><dt>%d</dt><dd>free file nodes in file system</dd><dt>%f</dt><dd>free blocks in file system</dd><dt>%i</dt><dd>file system ID in hex</dd><dt>%l</dt><dd>maximum length of filenames</dd><dt>%n</dt><dd>file name</dd><dt>%s</dt><dd>block size (for faster transfers)</dd><dt>%S</dt><dd>fundamental block size (for block counts)</dd><dt>%t</dt><dd>file system type in hex</dd><dt>%T</dt><dd>file system type in human readable form</dd></dl><h3 id="terse-is-equivalent-to-the-following-format" tabindex="-1">--terse is equivalent to the following FORMAT: <a class="header-anchor" href="#terse-is-equivalent-to-the-following-format" aria-label="Permalink to &quot;\\--terse is equivalent to the following FORMAT:&quot;">​</a></h3><blockquote><p>%n %s %b %f %u %g %D %i %h %t %T %X %Y %Z %W %o</p></blockquote><h3 id="terse-file-system-is-equivalent-to-the-following-format" tabindex="-1">--terse --file-system is equivalent to the following FORMAT: <a class="header-anchor" href="#terse-file-system-is-equivalent-to-the-following-format" aria-label="Permalink to &quot;\\--terse \\--file-system is equivalent to the following FORMAT:&quot;">​</a></h3><blockquote><p>%n %i %l %t %s %S %b %f %a %c %d</p></blockquote><p>NOTE: your shell may have its own version of stat, which usually supersedes the version described here. Please refer to your shell&#39;s documentation for details about the options it supports.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Michael Meskes.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>stat</strong>(2), <strong>statfs</strong>(2), <strong>statx</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/stat%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/stat\\</a>&gt; <br> or available locally via: info &#39;(coreutils) stat invocation&#39;</p>',27);function c(t,f,m,h,u,p){return d(),a("div",null,[s("h1",n,o(t.$params.man),1),l])}const y=e(r,[["render",c]]);export{b as __pageData,y as default};
